<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\{DB,Http,Redis,Schema,Storage};use Throwable;
class CheckConfiguration extends Command{
 protected$signature='lenspic:check-configuration {--environment=}';protected$description='Run non-destructive LensPic launch configuration checks without exposing secrets';private array$rows=[];private int$worst=0;
 public function handle():int{$environment=(string)($this->option('environment')?:app()->environment());$production=in_array($environment,['staging','production'],true);$this->check('Application key',filled(config('app.key')),'APP_KEY is missing.');$this->check('Debug mode',!$production||!config('app.debug'),'APP_DEBUG must be false outside local.');$this->check('Application URL',!$production||str_starts_with((string)config('app.url'),'https://'),'APP_URL must use HTTPS.',true);$this->check('Environment name',!$production||app()->environment()===$environment,'Loaded APP_ENV differs from requested audit environment.',true);$this->attempt('Database connection',fn()=>DB::select('select 1'));foreach(['sessions','jobs','failed_jobs','notifications','media_assets','media_variants','storage_ledger_entries','media_quota_usage_events','studio_team_memberships','team_invitations','subscriptions','wallets','wallet_ledger_entries','financial_transactions','biometric_consents','face_search_subjects']as$table)$this->check('Table '.$table,Schema::hasTable($table),'Required table is missing.');$queue=config('queue.default');$this->check('Queue driver',!$production||$queue==='redis','Production queue must use Redis; current: '.$queue);$cache=config('cache.default');$this->check('Cache store',!$production||$cache==='redis','Production cache should use Redis; current: '.$cache,true);$session=config('session.driver');$this->check('Session driver',!$production||in_array($session,['redis','database'],true),'Production sessions must use Redis or database.');$this->check('Secure session',!$production||(config('session.secure')&&config('session.http_only')&&config('session.same_site')==='lax'),'Secure/HttpOnly/SameSite session settings are incomplete.');if($production&&in_array('redis',[$queue,$cache,$session],true))$this->attempt('Redis connection',fn()=>Redis::connection()->ping());$disk=config('media.disk');$this->check('Private media disk',filled($disk)&&array_key_exists($disk,config('filesystems.disks')),'MEDIA_DISK is not configured.');if($disk)$this->attempt('Media disk access',fn()=>Storage::disk($disk)->exists('.lenspic-configuration-check'));$this->check('Image extensions',extension_loaded('gd')&&extension_loaded('exif')&&extension_loaded('fileinfo'),'GD, EXIF and fileinfo are required.');$this->check('Image formats',function_exists('imagejpeg')&&function_exists('imagepng')&&function_exists('imagewebp'),'GD must support JPEG, PNG and WebP.');$this->check('Temporary directory',is_writable(sys_get_temp_dir()),'PHP temporary directory is not writable.');$this->check('Storage directories',is_writable(storage_path())&&is_writable(base_path('bootstrap/cache')),'storage or bootstrap/cache is not writable.');$this->check('Mail transport',!$production||config('mail.default')!=='log','MAIL_MAILER=log cannot deliver production mail.');$this->check('Razorpay',!$production||(filled(config('services.razorpay.key_id'))&&filled(config('services.razorpay.key_secret'))&&filled(config('services.razorpay.webhook_secret'))),'Razorpay key, secret and webhook secret are required before payments.');$provider=config('face.provider');$this->check('Face provider',!$production||$provider!=='fake','FACE_PROVIDER=fake is forbidden outside local.');if($production&&$provider==='python'){$this->check('Face API authentication',filled(config('face.python_token')),'Face API token is missing.');$url=rtrim((string)config('face.python_url'),'/').config('services.face_recognition.health_path','/health');$this->attempt('Face API health',fn()=>Http::timeout(3)->get($url)->throw());}$this->check('CloudFront signer',config('media.delivery_driver')!=='cloudfront'||(filled(config('media.cloudfront.domain'))&&filled(config('media.cloudfront.key_pair_id'))&&is_readable((string)config('media.cloudfront.private_key_path'))),'CloudFront signer is incomplete.');$this->check('OTP test mode',!$production||!config('otp.test_mode'),'OTP_TEST_MODE must be false.',false);$this->check('OTP delivery',!$production||config('otp.driver')!=='log','OTP_DRIVER=log cannot deliver production OTPs.');if(config('otp.driver')==='whatsapp'){try{app(\App\Services\WhatsAppOtpSender::class)->validateConfiguration();$this->check('Meta WhatsApp configuration',true);}catch(\RuntimeException$e){$this->check('Meta WhatsApp configuration',false,$e->getMessage());}}if(config('otp.default_channel')==='sms'||config('otp.driver')==='sms'||filled(config('services.twilio.account_sid'))){try{app(\App\Services\Otp\TwilioVerifyOtpProvider::class)->validateConfiguration();$this->check('Twilio Verify configuration',true);}catch(\RuntimeException$e){$this->check('Twilio Verify configuration',false,$e->getMessage());}}$this->check('Horizon queues',collect(config('horizon.defaults.supervisor-1.queue',[]))->contains('media-high'),'Horizon does not cover media-high.');$this->table(['Status','Check','Message'],$this->rows);$this->line('No secret values were printed.');return$this->worst;}
 private function attempt(string$name,callable$callback):void{try{$callback();$this->check($name,true,'');}catch(Throwable$e){$this->check($name,false,'Connection/check failed: '.class_basename($e));}}
 private function check(string$name,bool$pass,string$message='',bool$warning=false):void{$status=$pass?'PASS':($warning?'WARN':'FAIL');$this->rows[]=[$status,$name,$pass?'Configured':$message];if(!$pass)$this->worst=max($this->worst,$warning?1:2);}
}
